mapper.sql:
WHERE IS_DELETED = 'N'
AND STATUS = #{assetStatus}
AND CATEGORY = #{category}
AND COMPANY = #{company}
AND UPPER(CATEGORY) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(COMPANY) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(NAME) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND UPPER(STATUS) LIKE UPPER(#{keywordLike}) ESCAPE '\'
AND ( UPPER(CATEGORY) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(COMPANY) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(NAME) LIKE UPPER(#{keywordLike}) ESCAPE '\' OR UPPER(STATUS) LIKE UPPER(#{keywordLike}) ESCAPE '\' )

mapper.select:
SELECT *
FROM ASSET
WHERE IS_DELETED = 'N'

    AND STATUS = #{assetStatus}


    AND CATEGORY = #{category}


    AND COMPANY = #{company}

ORDER BY CREATED_AT DESC

mapper.update:
UPDATE asset
SET maintenance_cycle = #{maintenanceCycle},
image = #{imagePath}
WHERE asset_id = #{assetId}

